/**
 * LUMA AI — SVG Sanitizer and Renderer
 * Normalizes SVG strings generated by LLMs:
 * - Strips markdown code fences (```xml, ```svg)
 * - Decodes escaped HTML entities
 * - Guarantees valid xmlns and viewBox for crisp, non-collapsing scaling
 * - Preserves shapes, paths, gradients, filters, markers, text, and styles
 */

export interface CleanSvgResult {
  svgHtml: string;
  isValid: boolean;
  viewBox: string;
}

export function cleanSvg(rawContent: string): CleanSvgResult {
  if (!rawContent || typeof rawContent !== 'string') {
    return {
      svgHtml: '',
      isValid: false,
      viewBox: '0 0 800 600'
    };
  }

  let text = rawContent.trim();

  // 1. Decode HTML-escaped SVG tags if model encoded them
  if (text.includes('&lt;svg') || text.includes('&lt;/svg&gt;')) {
    text = text
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&amp;/g, '&');
  }

  // 2. Strip markdown code fences (e.g., ```svg\n...\n``` or ```xml\n...\n```)
  text = text.replace(/^```[a-zA-Z0-9_-]*\s*\n?/i, '');
  text = text.replace(/\n?```\s*$/i, '');
  text = text.trim();

  // 3. Locate the opening <svg and closing </svg>
  const svgOpenIdx = text.search(/<svg\b/i);
  const svgCloseIdx = text.search(/<\/svg>/i);

  if (svgOpenIdx === -1) {
    return {
      svgHtml: rawContent,
      isValid: false,
      viewBox: '0 0 800 600'
    };
  }

  let svgSnippet = svgCloseIdx !== -1
    ? text.slice(svgOpenIdx, svgCloseIdx + 6)
    : text.slice(svgOpenIdx) + '</svg>';

  // 4. Extract opening tag attributes
  const openTagMatch = svgSnippet.match(/<svg([^>]*)>/i);
  if (!openTagMatch) {
    return {
      svgHtml: svgSnippet,
      isValid: true,
      viewBox: '0 0 800 600'
    };
  }

  const origAttributes = openTagMatch[1];
  let newAttributes = origAttributes;

  // Ensure xmlns is present
  if (!/xmlns\s*=/i.test(newAttributes)) {
    newAttributes = ` xmlns="http://www.w3.org/2000/svg"` + newAttributes;
  }

  // Extract or synthesize viewBox
  const viewBoxMatch = newAttributes.match(/viewBox\s*=\s*["']([^"']+)["']/i);
  let resolvedViewBox = '0 0 800 600';

  if (viewBoxMatch) {
    resolvedViewBox = viewBoxMatch[1].trim();
  } else {
    // Attempt to extract numeric width and height
    const widthMatch = newAttributes.match(/\bwidth\s*=\s*["']?(\d+(?:\.\d+)?)(?:px)?["']?/i);
    const heightMatch = newAttributes.match(/\bheight\s*=\s*["']?(\d+(?:\.\d+)?)(?:px)?["']?/i);

    if (widthMatch && heightMatch) {
      const w = parseFloat(widthMatch[1]);
      const h = parseFloat(heightMatch[1]);
      if (w > 0 && h > 0) {
        resolvedViewBox = `0 0 ${w} ${h}`;
        newAttributes += ` viewBox="${resolvedViewBox}"`;
      } else {
        newAttributes += ` viewBox="0 0 800 600"`;
      }
    } else {
      newAttributes += ` viewBox="0 0 800 600"`;
    }
  }

  // Ensure responsive sizing by replacing fixed px dimensions on the root element
  // while preserving the viewBox
  newAttributes = newAttributes
    .replace(/\bwidth\s*=\s*["'][^"']+["']/gi, 'width="100%"')
    .replace(/\bheight\s*=\s*["'][^"']+["']/gi, 'height="100%"');

  if (!/width\s*=/i.test(newAttributes)) {
    newAttributes += ' width="100%"';
  }
  if (!/height\s*=/i.test(newAttributes)) {
    newAttributes += ' height="100%"';
  }

  // Replace opening tag
  const sanitizedSvg = svgSnippet.replace(/<svg[^>]*>/i, `<svg${newAttributes}>`);

  return {
    svgHtml: sanitizedSvg,
    isValid: true,
    viewBox: resolvedViewBox
  };
}
